        ListNode prev = null;
        curr = head;
        ListNode nextNode = null;

        for (int i = 0; i < k; i++) {
            nextNode = curr.next;
            curr.next = prev;
            prev = curr;
            curr = nextNode;
        }

        // 3. 遞迴處理剩餘部分
        head.next = reverseKGroup(curr, k);

        // 4. 返回新頭節點
        return prev;
    }
}


